38	
39	const MAIN_PAGE_TYPE = pageMain;
40	const PRIMARY_SHEET_ID: MainTheatreSheetId = "intro";
41	const FRAME_MS = 1000 / 30;
42	const AUTHOR_MODE: MainTheatreMode = "author";
43	const STATUS_ID = "main-theatre-status";
44	const EXPORT_BUTTON_ID = "main-theatre-export";
45	const SHEET_SELECT_ID = "main-theatre-sheet-select";
46	const MATCH_PREV_BUTTON_ID = "main-theatre-match-prev";
