48	function sanitizeMainTheatreState(
49	  state: Record<string, unknown> | null,
50	): Record<string, unknown> | null {
51	  if (!state) return null;
52	  const sheetsByIdValue = state.sheetsById;
53	  if (
54	    sheetsByIdValue == null ||
55	    typeof sheetsByIdValue !== "object" ||
56	    Array.isArray(sheetsByIdValue)
57	  ) {
58	    return state;
59	  }
60	  const sheetsById = sheetsByIdValue as Record<string, unknown>;
61	  const nextSheetsById: Record<string, unknown> = {};
62	  MAIN_THEATRE_SHEET_IDS.forEach((sheetId) => {
63	    if (!Object.prototype.hasOwnProperty.call(sheetsById, sheetId)) return;
64	    nextSheetsById[sheetId] = sheetsById[sheetId];
65	  });
66	  return {
67	    ...state,
68	    sheetsById: nextSheetsById,
69	  };
70	}
71	
72	function resolveMainAuthorMode(): boolean {
73	  return EnvSetup.hasQueryFlag(
74	    MAIN_THEATRE_QUERY_KEY,
75	    MAIN_THEATRE_QUERY_ENABLED,
76	  );
77	}
78	
79	function readMainTheatreFileState(): Record<string, unknown> | null {
80	  return sanitizeMainTheatreState(mainState as Record<string, unknown>);
81	}
82	
83	function seedSavedMainStateFromFileState(
84	  fileState: Record<string, unknown> | null,
85	): void {
86	  TheatreStateStorageService.seedFromFileState(
87	    fileState,
88	    MAIN_THEATRE_STORAGE_OPTIONS,
89	  );
90	}
91	
92	function clearMainStudioPersistenceOnce(fileState: Record<string, unknown> | null): void {
93	  TheatreStateStorageService.clearStudioPersistenceOnce(fileState, {
94	    ...MAIN_THEATRE_STORAGE_OPTIONS,
95	    pageType: MAIN_PAGE_TYPE,
96	  });
97	}
