99	export class MainTheatreBridge {
100	  private _authorSheetId: MainTheatreSheetId = PRIMARY_SHEET_ID;
101	  private _playing = false;
102	  private _sampling = false;
103	  private _disposed = false;
104	  private _lastSampleAt = 0;
105	  private _recordScrub: MainTheatreScrub | null = null;
106	  private _unsubscribeValues: (() => void) | null = null;
107	  private _unsubscribePlaying: (() => void) | null = null;
108	  private _unsubscribeSelection: (() => void) | null = null;
109	  private _syncingStudioSelection = false;
110	  private readonly _sheetById = new Map<
111	    MainTheatreSheetId,
112	    TheatreSheetPort<MainTheatreValue, MainTheatreProps>
113	  >();
114	  private readonly _objectBySheetId = new Map<
115	    MainTheatreSheetId,
116	    MainTheatreObject
117	  >();
118	  private readonly _sequenceBySheetId = new Map<
119	    MainTheatreSheetId,
120	    MainTheatreSequence
121	  >();
122	  private readonly _rig = new MainSceneRig();
123	  private readonly _hooks: MainTheatreBridgeHooks;
124	  private readonly _engine: Engine;
125	  private readonly _controls: OrbitControls;
126	  private readonly _onControlsStart: () => void;
127	  private readonly _onControlsEnd: () => void;
128	  private readonly _onControlsChange: () => void;
129	  private readonly _onExportClick: () => void;
130	  private readonly _onSheetChange: (event: Event) => void;
131	  private readonly _onMatchPrevClick: () => void;
132	
133	  private constructor(
134	    engine: Engine,
135	    controls: OrbitControls,
136	    hooks: MainTheatreBridgeHooks,
137	  ) {
138	    this._engine = engine;
139	    this._controls = controls;
140	    this._hooks = hooks;
141	    this._onControlsStart = () => this._recordStart();
142	    this._onControlsEnd = () => this._recordEnd();
143	    this._onControlsChange = () => this._recordFrame();
144	    this._onExportClick = () => void this._exportSaveFile();
145	    this._onSheetChange = (event) => {
146	      const select = event.currentTarget;
147	      if (!(select instanceof HTMLSelectElement)) return;
148	      this._setAuthorSheetId(select.value);
149	    };
150	    this._onMatchPrevClick = () => this._matchFromPrevious();
151	  }
152	
153	  static async create(
154	    engine: Engine,
155	    controls: OrbitControls,
156	    hooks: MainTheatreBridgeHooks,
157	  ): Promise<MainTheatreBridge | null> {
158	    if (EnvSetup.getPageType() !== MAIN_PAGE_TYPE) return null;
159	    if (!resolveMainAuthorMode()) {
160	      return null;
161	    }
162	    try {
163	      const bridge = new MainTheatreBridge(engine, controls, hooks);
164	      await bridge._init();
165	      return bridge;
166	    } catch (error) {
167	      return null;
168	    }
169	  }
170	
171	  dispose(): void {
172	    if (this._disposed) return;
173	    this._disposed = true;
174	    this._controls.removeEventListener("start", this._onControlsStart);
175	    this._controls.removeEventListener("end", this._onControlsEnd);
176	    this._controls.removeEventListener("change", this._onControlsChange);
177	    this._recordScrub?.discard();
178	    this._recordScrub = null;
179	    this._unsubscribeValues?.();
180	    this._unsubscribePlaying?.();
181	    this._unsubscribeSelection?.();
182	    this._sequenceBySheetId.clear();
183	    TheatreStudioService.removeAuthorControl(STATUS_ID, "status");
184	    TheatreStudioService.removeAuthorControl(
185	      EXPORT_BUTTON_ID,
186	      "button",
187	      this._onExportClick as EventListener,
188	    );
189	    TheatreStudioService.removeAuthorControl(
190	      SHEET_SELECT_ID,
191	      "select",
192	      this._onSheetChange as EventListener,
193	    );
194	    TheatreStudioService.removeAuthorControl(
195	      MATCH_PREV_BUTTON_ID,
196	      "button",
197	      this._onMatchPrevClick as EventListener,
198	    );
199	  }
200	
201	  private async _init(): Promise<void> {
202	    await TheatreStudioService.ensureReady(MAIN_PAGE_TYPE);
203	    const fileState = readMainTheatreFileState();
204	    clearMainStudioPersistenceOnce(fileState);
205	    TheatreStudioService.restoreUi();
206	    seedSavedMainStateFromFileState(fileState);
207	    const savedState = fileState ? null : this._readSavedState();
208	    const project = TheatreProjectSession.open<
209	      MainTheatreValue,
210	      MainTheatreProps
211	    >(
212	      MAIN_THEATRE_PROJECT_ID,
213	      {
214	        state: fileState ?? savedState ?? undefined,
215	      },
216	    );
217	    await project.ready;
218	    MAIN_THEATRE_SHEET_IDS.forEach((sheetId) => {
219	      const sheet = TheatreSheetSession.open(project, sheetId);
220	      const object = sheet.object(
221	        MAIN_THEATRE_OBJECT_ID,
222	        this._readSceneValues(),
223	        {
224	          reconfigure: true,
225	        },
226	      );
227	      this._sheetById.set(sheetId, sheet);
228	      this._objectBySheetId.set(sheetId, object);
229	      this._sequenceBySheetId.set(sheetId, TheatreSequenceSession.get(sheet));
230	    });
231	    this._attachSheet(PRIMARY_SHEET_ID);
232	    this._unsubscribeSelection = TheatreStudioService.bindSelectionChange(
233	      (selection) => {
234	        this._syncAuthorSheetFromStudioSelection(selection);
235	      },
236	    );
237	    this._bindControls();
238	    this._renderSheetSelector();
239	    this._renderMatchPrevButton();
240	    this._renderExportButton();
241	    this._renderStatus(
242	      fileState
243	        ? `FILE SAVEFILE LOADED (${MAIN_THEATRE_SHEET_IDS.length} SHEETS)`
244	        : savedState
245	        ? `SAVEFILE LOADED (${MAIN_THEATRE_SHEET_IDS.length} SHEETS)`
246	        : `THEATRE READY (${MAIN_THEATRE_SHEET_IDS.length} SHEETS)`,
247	    );
248	    this._hooks.onModeChange(AUTHOR_MODE);
249	    this._hooks.onPlaybackChange(this._playing);
250	  }
251	
252	  private _attachSheet(sheetId: MainTheatreSheetId): void {
253	    const sheet = this._sheetById.get(sheetId);
254	    const object = this._objectBySheetId.get(sheetId);
255	    const sequence = this._sequenceBySheetId.get(sheetId);
256	    if (!sheet || !object || !sequence) return;
257	    this._unsubscribeValues?.();
258	    this._unsubscribePlaying?.();
259	    this._authorSheetId = sheetId;
260	    this._unsubscribeValues = TheatrePlaybackService.bindValues(
261	      object,
262	      (values) => {
263	        if (sheetId !== this._authorSheetId) return;
264	        this._rig.apply(this._engine, mergeMainSceneState(values));
265	        this._syncControlsToCameraState();
266	      },
267	    );
268	    this._unsubscribePlaying = TheatrePlaybackService.bindPlaying(
269	      sequence,
270	      (playing) => {
271	        if (sheetId !== this._authorSheetId) return;
272	        this._playing = playing;
273	        this._hooks.onPlaybackChange(playing);
274	      },
275	    );
276	    this._syncStudioSelection(sheet, object);
277	    this._rig.apply(this._engine, mergeMainSceneState(object.value));
278	    this._syncControlsToCameraState();
279	  }
280	
281	  private _syncStudioSelection(
282	    sheet: TheatreSheetPort<MainTheatreValue, MainTheatreProps>,
283	    object: MainTheatreObject,
284	  ): void {
285	    this._syncingStudioSelection = true;
286	    try {
287	      TheatreStudioService.setSelection([sheet, object]);
288	    } finally {
289	      this._syncingStudioSelection = false;
290	    }
291	  }
292	
293	  private _syncAuthorSheetFromStudioSelection(
294	    selection: TheatreSelectionItemPort[],
295	  ): void {
296	    if (this._syncingStudioSelection) return;
297	    const nextSheetId = this._findSelectedSheetId(selection);
298	    if (!nextSheetId) return;
299	    if (nextSheetId === this._authorSheetId) return;
300	    this._attachSheet(nextSheetId);
301	    this._syncSheetSelector();
302	    this._renderStatus(`ACTIVE SHEET ${nextSheetId.toUpperCase()}`);
303	  }
304	
305	  private _findSelectedSheetId(
306	    selection: TheatreSelectionItemPort[],
307	  ): MainTheatreSheetId | null {
308	    for (const [sheetId, sheet] of this._sheetById.entries()) {
309	      if (selection.includes(sheet)) return sheetId;
310	    }
311	    for (const [sheetId, object] of this._objectBySheetId.entries()) {
312	      if (selection.includes(object)) return sheetId;
313	    }
314	    return null;
315	  }
316	
317	  private _bindControls(): void {
318	    this._controls.addEventListener("start", this._onControlsStart);
319	    this._controls.addEventListener("end", this._onControlsEnd);
320	    this._controls.addEventListener("change", this._onControlsChange);
321	  }
322	
323	  private _recordStart(): void {
324	    if (this._playing) return;
325	    this._sampling = true;
326	    this._recordScrub?.discard();
327	    this._recordScrub = TheatreStudioService.createScrub<
328	      MainTheatreValue,
329	      MainTheatreProps
330	    >();
331	    this._recordFrame(true);
332	  }
333	
334	  private _recordEnd(): void {
335	    if (this._playing) return;
336	    this._recordFrame(true);
337	    this._sampling = false;
338	    this._recordScrub?.commit();
339	    this._recordScrub = null;
340	  }
341	
342	  private _recordFrame(force = false): void {
343	    if (this._playing) return;
344	    if (!force && !this._sampling) return;
345	    const object = this._objectBySheetId.get(this._authorSheetId);
346	    const scrub = this._recordScrub;
347	    if (!object || !scrub) return;
348	    const now = performance.now();
349	    if (!force && now - this._lastSampleAt < FRAME_MS) return;
350	    this._lastSampleAt = now;
351	    const values = this._readCameraValues();
352	    const cameraScrub = scrub as unknown as MainTheatreScrubCameraPort;
353	    cameraScrub.capture(({ set }) => {
354	      set(object.props.camera, values.camera);
355	    });
356	  }
357	
358	  private _readSceneValues(): MainTheatreValue {
359	    return this._rig.read(this._engine);
360	  }
361	
362	  private _readCameraValues(): MainCameraTheatreValue {
363	    const state = this._rig.read(this._engine);
364	    return { camera: state.camera };
365	  }
366	
367	  private get _currentObject(): MainTheatreObject | null {
368	    return this._objectBySheetId.get(this._authorSheetId) ?? null;
369	  }
370	
371	  private get _currentSequence(): MainTheatreSequence | null {
372	    return this._sequenceBySheetId.get(this._authorSheetId) ?? null;
373	  }
374	
375	  private _setAuthorSheetId(sheetId: string): void {
376	    if (!this._isTheatreSheetId(sheetId)) return;
377	    if (sheetId === this._authorSheetId) return;
378	    this._attachSheet(sheetId);
379	    this._syncSheetSelector();
380	    this._renderStatus(`ACTIVE SHEET ${sheetId.toUpperCase()}`);
381	  }
382	
383	  private _matchFromPrevious(): void {
384	    const authorSheetIds =
385	      MAIN_THEATRE_SHEET_IDS as readonly MainTheatreSheetId[];
386	    const currentIndex = authorSheetIds.indexOf(this._authorSheetId);
387	    if (currentIndex <= 0) {
388	      this._renderStatus("NO PREVIOUS SHEET");
389	      return;
390	    }
391	    const previousSheetId = authorSheetIds[currentIndex - 1];
392	    const previousObject = this._objectBySheetId.get(previousSheetId) ?? null;
393	    const currentObject = this._currentObject;
394	    const currentSequence = this._currentSequence;
395	    if (!previousObject || !currentObject || !currentSequence) {
396	      this._renderStatus("MATCH FAILED");
397	      return;
398	    }
399	    currentObject.initialValue = previousObject.value;
400	    this._writeMatchStartKeyframe(
401	      currentObject,
402	      currentSequence,
403	      previousObject,
404	    );
405	    this._rig.apply(this._engine, mergeMainSceneState(previousObject.value));
406	    this._syncControlsToCameraState();
407	    this._renderStatus(`MATCHED ${previousSheetId.toUpperCase()}`);
408	  }
409	
410	  private _writeMatchStartKeyframe(
411	    currentObject: MainTheatreObject,
412	    currentSequence: MainTheatreSequence,
413	    previousObject: MainTheatreObject,
414	  ): void {
415	    const previousPosition = currentSequence.position;
416	    const scrub = TheatreStudioService.createScrub<
417	      MainTheatreValue,
418	      MainTheatreProps
419	    >();
420	    currentSequence.position = 0;
421	    scrub.capture(({ set }) => {
422	      set(currentObject.props, previousObject.value);
423	    });
424	    scrub.commit();
425	    currentSequence.position = previousPosition;
426	  }
427	
428	  private _readSavedState(): Record<string, unknown> | null {
429	    return TheatreStateStorageService.read({
430	      ...MAIN_THEATRE_STORAGE_OPTIONS,
431	      sanitize: sanitizeMainTheatreState,
432	      validate: (state) => this._isReadableTheatreState(state),
433	    });
434	  }
435	
436	  private async _exportSaveFile(): Promise<void> {
437	    const saveFile = TheatreStudioService.createContentOfSaveFile(
438	      MAIN_THEATRE_PROJECT_ID,
439	    );
440	    if (!saveFile) {
441	      this._renderStatus("EXPORT FAILED");
442	      return;
443	    }
444	    const sanitizedSaveFile = sanitizeMainTheatreState(saveFile) ?? saveFile;
445	    const raw = JSON.stringify(sanitizedSaveFile, null, 2);
446	    TheatreStateStorageService.writeRaw(raw, MAIN_THEATRE_STORAGE_OPTIONS);
447	    if (!this._downloadSaveFile(raw, "main.json")) {
448	      this._renderStatus("EXPORT BLOCKED");
449	      return;
450	    }
451	    this._renderStatus("MAIN.JSON DOWNLOADED");
452	  }
453	
454	  private _syncControlsToCameraState(): void {
455	    const target = this._engine.getCameraTarget().position;
456	    this._controls.target.copy(target);
457	    this._controls.update();
458	  }
459	
460	  private _renderExportButton(): void {
461	    TheatreStudioService.renderAuthorButton(
462	      {
463	        id: EXPORT_BUTTON_ID,
464	        text: "EXPORT STATE JSON",
465	        bottom: "16px",
466	      },
467	      this._onExportClick,
468	    );
469	  }
470	
471	  private _renderSheetSelector(): void {
472	    TheatreStudioService.renderAuthorSelect(
473	      {
474	        id: SHEET_SELECT_ID,
475	        bottom: "92px",
476	        value: this._authorSheetId,
477	        options: MAIN_THEATRE_SHEET_IDS.map((sheetId) => ({
478	          value: sheetId,
479	          text: sheetId,
480	        })),
481	      },
482	      this._onSheetChange,
483	    );
484	  }
485	
486	  private _renderMatchPrevButton(): void {
487	    TheatreStudioService.renderAuthorButton(
488	      {
489	        id: MATCH_PREV_BUTTON_ID,
490	        text: "MATCH FROM PREV",
491	        bottom: "130px",
492	      },
493	      this._onMatchPrevClick,
494	    );
495	  }
496	
497	  private _syncSheetSelector(): void {
498	    if (typeof document === "undefined") return;
499	    const select = document.getElementById(
500	      SHEET_SELECT_ID,
501	    ) as HTMLSelectElement | null;
502	    if (!select) return;
503	    select.value = this._authorSheetId;
504	  }
505	
506	  private _renderStatus(text: string): void {
507	    TheatreStudioService.renderAuthorStatus(STATUS_ID, text);
508	  }
509	
510	  private _downloadSaveFile(raw: string, fileName: string): boolean {
511	    return TheatreStudioService.downloadFile(raw, { fileName });
512	  }
513	
514	  private _isTheatreSheetId(value: string): value is MainTheatreSheetId {
515	    return (MAIN_THEATRE_SHEET_IDS as readonly string[]).includes(value);
516	  }
517	
518	  private _isReadableTheatreState(
519	    value: Record<string, unknown> | null,
520	  ): value is Record<string, unknown> {
521	    if (!value) return false;
522	    const sheetsById = value.sheetsById;
523	    if (
524	      sheetsById == null ||
525	      typeof sheetsById !== "object" ||
526	      Array.isArray(sheetsById)
527	    ) {
528	      return false;
529	    }
530	    return true;
531	  }
532	}
