33	function sanitizeWorksSaveFile(
34	  saveFile: Record<string, unknown> | null,
35	): Record<string, unknown> | null {
36	  if (!saveFile) return null;
37	  const sheetsByIdValue = saveFile.sheetsById;
38	  if (
39	    sheetsByIdValue == null ||
40	    typeof sheetsByIdValue !== "object" ||
41	    Array.isArray(sheetsByIdValue)
42	  ) {
43	    return saveFile;
44	  }
45	  const sheetsById = sheetsByIdValue as Record<string, unknown>;
46	  const nextSheetsById: Record<string, unknown> = {};
47	  WORKS_THEATRE_SHEET_IDS.forEach((sheetId) => {
48	    if (!Object.prototype.hasOwnProperty.call(sheetsById, sheetId)) return;
49	    nextSheetsById[sheetId] = sheetsById[sheetId];
50	  });
51	  return {
52	    ...saveFile,
53	    sheetsById: nextSheetsById,
54	  };
55	}
