438	    const previousObject = this._objectBySheetId.get(previousSheetId) ?? null;
439	    const previousSequence = this._sequenceBySheetId.get(previousSheetId) ?? null;
440	    const currentObject = this._currentObject;
441	    const currentSequence = this._sequenceBySheetId.get(this._authorSheetId) ?? null;
442	    if (!previousObject || !previousSequence || !currentObject || !currentSequence) {
443	      this._renderStatus("MATCH FAILED");
444	      return;
445	    }
446	
447	    const previousEndValues = this._readSheetEndValues(
448	      previousSheetId,
449	      previousObject,
450	      previousSequence,
451	    );
452	    if (!previousEndValues) {
453	      this._renderStatus("MATCH FAILED");
