473	  private _readSheetEndValues(
474	    sheetId: AboutTheatreSheetId,
475	    object: AboutTheatreObject,
476	    sequence: TheatreSequencePort,
477	  ): AboutTheatreValue | null {
478	    const previousPosition = sequence.position;
479	    try {
480	      sequence.pause();
